JS['nashr']='''let category='all',savedOnly=false,selected;
function render(){const ids=read(),items=data.filter(p=>(category==='all'||category===p.category)&&(!savedOnly||ids.includes(p.id)));$('#saved-count').textContent=ids.length;$('#saved-toggle').setAttribute('aria-pressed',savedOnly);$('#empty').hidden=!!items.length;$('#articles').innerHTML=items.map((p,i)=>`<article class="story">${p.image?`<img class="story-image" src="images/${p.image}" width="800" height="600" alt="${p.id==='city'?'Registon maydoni':'Shohi Zinda koshinlari'}">`:''}<span class="eyebrow">${p.tag}</span><button class="story-read" data-read="${p.id}"><h2>${p.name}</h2></button><p>${p.intro}</p><div class="story-actions"><span>TAHRIRIY MASHQ / ${i+1}</span><button data-save="${p.id}" aria-label="${p.name}: ${ids.includes(p.id)?'saqlangandan olish':'saqlash'}" aria-pressed="${ids.includes(p.id)}">${ids.includes(p.id)?'✓ Saqlangan':'Saqlash +'}</button></div></article>`).join('');}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.filter){category=b.dataset.filter;$$('[data-filter]').forEach(x=>x.setAttribute('aria-pressed',x===b));render();}if(b.dataset.save){toggle(b.dataset.save);render();if(persistent)$('#status').textContent='Saqlangan maqolalar yangilandi.';}if(b.dataset.read){selected=b.dataset.read;const p=data.find(p=>p.id===selected);$('#reader-title').textContent=p.name;$('#reader-body').innerHTML=(p.image?`<img src="images/${p.image}" alt="Maqola uchun me’moriy surat">`:'')+'<p>'+p.intro+'</p>'+p.text.map(t=>'<p>'+t+'</p>').join('');syncSave();openDialog(b);}});function syncSave(){const on=read().includes(selected);$('#reader-save').setAttribute('aria-pressed',on);$('#reader-save').textContent=on?'✓ Saqlangan':'Maqolani saqlash +';}$('#reader-save').addEventListener('click',()=>{toggle(selected);syncSave();render();});$('#saved-toggle').addEventListener('click',()=>{savedOnly=!savedOnly;render();});render();
'''

