MODELS['ziyo']='''export function grade(id,answer){const p=data.find(p=>p.id===id);return !!p&&Number.isInteger(answer)&&answer===p.correct;}
'''
JS['ziyo']='''let selected='structure';function render(){const ids=read();$('#progress-label').textContent=ids.length+' / '+data.length+' modul tugallangan';$('#progress-fill').style.width=(ids.length/data.length*100)+'%';$('#lesson-tabs').innerHTML=data.map((p,i)=>`<button data-lesson="${p.id}" aria-pressed="${p.id===selected}"><span>${ids.includes(p.id)?'✓':i+1}</span>${p.name}</button>`).join('');}
function lesson(){const p=data.find(p=>p.id===selected);$('#lesson-tag').textContent=p.tag+' · '+p.minutes;$('#lesson-title').textContent=p.title;$('#lesson-text').textContent=p.text;$('#lesson-code').textContent=p.example;$('#question').textContent=p.question;$('#answers').innerHTML=p.answers.map((a,i)=>`<label><input type="radio" name="answer" value="${i}" required><span></span></label>`).join('');$$('#answers label span').forEach((s,i)=>s.textContent=p.answers[i]);$('#feedback').textContent='';$('#feedback').removeAttribute('data-result');$('#next').hidden=true;render();}
document.addEventListener('click',e=>{const b=e.target.closest('[data-lesson]');if(b){selected=b.dataset.lesson;lesson();}});$('#quiz').addEventListener('submit',e=>{e.preventDefault();$('#next').hidden=true;const choice=new FormData(e.currentTarget).get('answer');if(choice===null){$('#feedback').textContent='Avval javobni tanlang.';return;}const p=data.find(p=>p.id===selected),correct=grade(selected,Number(choice));$('#feedback').dataset.result=correct?'correct':'wrong';$('#feedback').textContent=(correct?'To‘g‘ri. ':'Yana urinib ko‘ring. ')+p.explanation;if(correct){commit([...read(),selected]);render();$('#next').hidden=data.at(-1).id===selected;}});$('#next').addEventListener('click',()=>{selected=data[data.findIndex(p=>p.id===selected)+1].id;lesson();$('#lesson-title').setAttribute('tabindex','-1');$('#lesson-title').focus();});lesson();
'''

