JS['meros']='''let category='all',savedOnly=false,selected;function render(){const ids=read(),items=data.filter(p=>(category==='all'||p.category===category)&&(!savedOnly||ids.includes(p.id)));$('#saved-count').textContent=ids.length;$('#saved-toggle').setAttribute('aria-pressed',savedOnly);$('#exhibit-count').textContent=items.length+' lavha / fotografik ekspozitsiya';$('#empty').hidden=!!items.length;$('#export').disabled=!ids.length;$('#exhibit-list').innerHTML=items.map((p,i)=>`<article class="exhibit"><span class="exhibit-number">${String(data.indexOf(p)+1).padStart(2,'0')}</span><button class="exhibit-image" data-read="${p.id}" aria-label="${p.name}: tafsilot"><img src="images/${p.image}" width="1000" height="700" alt="${p.name}"></button><div class="exhibit-copy"><span class="eyebrow">${p.tag}</span><h3>${p.name}</h3><p>${p.text}</p><button class="btn" data-save="${p.id}" aria-label="${p.name}: ${ids.includes(p.id)?'saqlangandan olish':'saqlash'}" aria-pressed="${ids.includes(p.id)}">${ids.includes(p.id)?'✓ Kolleksiyada':'Kolleksiyaga olish +'}</button></div></article>`).join('');}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.filter){category=b.dataset.filter;$$('[data-filter]').forEach(x=>x.setAttribute('aria-pressed',x===b));render();}if(b.dataset.save){toggle(b.dataset.save);render();if(persistent)$('#status').textContent='Shaxsiy kolleksiya yangilandi.';}if(b.dataset.read){selected=b.dataset.read;const p=data.find(p=>p.id===selected);$('#reader-title').textContent=p.name;$('#reader-body').innerHTML=`<img src="images/${p.image}" alt="${p.name}"><p>${p.text}</p><p><a href="${p.source}">Uzbekistan Travel — rasmiy ma’lumot ↗</a></p><p><a href="CREDITS.md">Surat muallifi va litsenziyasi ↗</a></p>`;syncSave();openDialog(b);}});function syncSave(){const on=read().includes(selected);$('#reader-save').setAttribute('aria-pressed',on);$('#reader-save').textContent=on?'✓ Kolleksiyada':'Kolleksiyaga olish +';}$('#reader-save').addEventListener('click',()=>{toggle(selected);syncSave();render();});$('#saved-toggle').addEventListener('click',()=>{savedOnly=!savedOnly;render();});$('#export').addEventListener('click',()=>download('meros-kolleksiya.txt','MEROS — mustaqil fotografik ekspozitsiya\\n'+read().map(id=>{const p=data.find(p=>p.id===id);return p.name+'\\n'+p.source;}).join('\\n\\n')));render();
'''

